"""Movement 12: source-preserved REAL REA durable process-restart checkpoint."""
from pathlib import Path
from hashlib import sha256
import argparse, json, shutil, subprocess
from systems.workspace.workstation import ProcessWorkstation
PIN="f0b9ef34c404c1c65f8167502db972b0bd708403"
REL=Path("src/domain/javascript/javascriptInvestigationCheckpoint.ts")
CONTENT="/**\n * Experimental, durable checkpoint for REA's bounded A/B investigation.\n * This file is added to the actual pinned REA source edition, not a mock.\n *\n * Local single-host contract: one exclusive lock writer, atomic rename with\n * fsync, checksum against accidental corruption, unique event IDs and source\n * provenance checks. A crash leaving the lock requires manual inspection.\n * A checksum is NOT an authentication or attestation mechanism.\n */\nimport { createHash } from \"node:crypto\";\nimport {\n  closeSync, existsSync, fsyncSync, mkdirSync, openSync, readFileSync,\n  renameSync, unlinkSync, writeSync,\n} from \"node:fs\";\nimport { dirname } from \"node:path\";\nimport {\n  advanceJavaScriptApplicationInvestigation,\n  matchJavaScriptApplicationVersions,\n  refineJavaScriptApplicationPairByObservations,\n  type ApplicationVersionNodePair,\n  type ApplicationVersionInputObservation,\n  type ApplicationVersionConstructedObservation,\n  type ApplicationVersionInvestigationAdvance,\n} from \"./javascriptApplicationVersionKeys.js\";\n\ntype Side = \"left\" | \"right\";\nexport type InvestigationDiskEvent =\n  | {readonly eventId: string; readonly kind: \"advance\"}\n  | {readonly eventId: string; readonly kind: \"capture\"; readonly side: Side;\n     readonly observation: ApplicationVersionInputObservation};\n\nexport interface InvestigationCheckpoint {\n  readonly schemaVersion: 1;\n  readonly upstreamCommit: string;\n  readonly investigationId: string;\n  readonly revision: number;\n  readonly pair: ApplicationVersionNodePair;\n  readonly leftSource: string;\n  readonly rightSource: string;\n  readonly left: readonly ApplicationVersionInputObservation[];\n  readonly right: readonly ApplicationVersionInputObservation[];\n  readonly acceptedContextIds: readonly string[];\n  readonly pending: ApplicationVersionConstructedObservation | null;\n  readonly status: ApplicationVersionInvestigationAdvance[\"status\"];\n  readonly events: readonly {\n    readonly eventId: string;\n    readonly eventHash: string;\n    readonly revision: number;\n    readonly resultingStatus: ApplicationVersionInvestigationAdvance[\"status\"];\n  }[];\n  readonly checksum: string;\n}\n\nconst PIN = \"f0b9ef34c404c1c65f8167502db972b0bd708403\";\nconst sha = (s: string): string => createHash(\"sha256\").update(s).digest(\"hex\");\nconst checksum = (value: Omit<InvestigationCheckpoint, \"checksum\">): string =>\n  sha(JSON.stringify(value));\n\nconst withoutChecksum = (value: InvestigationCheckpoint) => {\n  const {checksum: ignored, ...rest} = value;\n  void ignored;\n  return rest;\n};\n\nconst validate = (value: InvestigationCheckpoint): void => {\n  if (value.schemaVersion !== 1 || value.upstreamCommit !== PIN ||\n      !Number.isSafeInteger(value.revision) || value.revision < 0 ||\n      !Array.isArray(value.events) || !Array.isArray(value.left) ||\n      !Array.isArray(value.right) || !Array.isArray(value.acceptedContextIds) ||\n      typeof value.investigationId !== \"string\" ||\n      value.investigationId.length === 0 ||\n      value.checksum !== checksum(withoutChecksum(value))) {\n    throw new Error(\"Checkpoint structure or checksum mismatch\");\n  }\n  if (!value.pair || typeof value.leftSource !== \"string\" ||\n      typeof value.rightSource !== \"string\") throw new Error(\"Checkpoint missing source pair\");\n  for (const [side, code] of [\n    [value.pair.left, value.leftSource],\n    [value.pair.right, value.rightSource],\n  ] as const) {\n    const digests = side.observations.map((o) => o.properties.source_sha256);\n    if (!digests.length || digests.some((d) => d !== sha(code)))\n      throw new Error(\"Source provenance mismatch\");\n  }\n  const matching = matchJavaScriptApplicationVersions(\n    [value.pair.left], [value.pair.right],\n  );\n  const pair = matching.pairs[0];\n  if (matching.pairs.length !== 1 || pair?.basis !== value.pair.basis ||\n      pair.confidence !== value.pair.confidence ||\n      pair.left.node_id !== value.pair.left.node_id ||\n      pair.right.node_id !== value.pair.right.node_id) {\n    throw new Error(\"Saved pair no longer matches native REA\");\n  }\n  if (value.revision !== value.events.length ||\n      new Set(value.events.map((e) => e.eventId)).size !== value.events.length ||\n      new Set(value.acceptedContextIds).size !== value.acceptedContextIds.length)\n    throw new Error(\"Checkpoint event history mismatch\");\n  // This also rejects duplicate observation context IDs on either side.\n  refineJavaScriptApplicationPairByObservations(\n    value.pair, value.left, value.right,\n  );\n};\n\nexport const readJavaScriptInvestigationCheckpoint = (\n  location: string,\n): InvestigationCheckpoint => {\n  const value: unknown = JSON.parse(readFileSync(location, \"utf8\"));\n  if (value === null || typeof value !== \"object\")\n    throw new Error(\"Checkpoint is not a JSON object\");\n  const checkpoint = value as InvestigationCheckpoint;\n  validate(checkpoint);\n  return checkpoint;\n};\n\nconst locked = <T>(location: string, body: () => T): T => {\n  mkdirSync(dirname(location), {recursive: true});\n  const path = location + \".lock\";\n  // A leftover lock after a hard crash stops writes until manual inspection.\n  const fd = openSync(path, \"wx\", 0o600);\n  try {\n    writeSync(fd, String(process.pid) + \"\\n\");\n    fsyncSync(fd);\n    return body();\n  } finally {\n    closeSync(fd);\n    unlinkSync(path);\n  }\n};\n\nconst durableReplace = (location: string, value: InvestigationCheckpoint): void => {\n  validate(value);\n  const temp = location + \".tmp-\" + String(process.pid);\n  const bytes = JSON.stringify(value) + \"\\n\";\n  const fd = openSync(temp, \"wx\", 0o600);\n  try {\n    writeSync(fd, bytes);\n    fsyncSync(fd);\n  } finally {\n    closeSync(fd);\n  }\n  try {\n    renameSync(temp, location);\n    const directoryFd = openSync(dirname(location), \"r\");\n    try { fsyncSync(directoryFd); } finally { closeSync(directoryFd); }\n  } finally {\n    if (existsSync(temp)) unlinkSync(temp);\n  }\n};\n\nexport const initializeJavaScriptInvestigationCheckpoint = (\n  location: string,\n  investigationId: string,\n  pair: ApplicationVersionNodePair,\n  leftSource: string,\n  rightSource: string,\n  left: readonly ApplicationVersionInputObservation[],\n  right: readonly ApplicationVersionInputObservation[],\n  acceptedContextIds: readonly string[],\n): InvestigationCheckpoint => locked(location, () => {\n  if (existsSync(location)) throw new Error(\"Checkpoint already exists; no overwrite\");\n  const step = advanceJavaScriptApplicationInvestigation(\n    pair, leftSource, rightSource, left, right, acceptedContextIds, null,\n  );\n  // Initial checkpoint records only the admitted evidence, not the proposal.\n  if (step.status === \"witnessed-difference\")\n    throw new Error(\"Initialization already has a witnessed difference\");\n  const content: Omit<InvestigationCheckpoint, \"checksum\"> = {\n    schemaVersion: 1, upstreamCommit: PIN, investigationId, revision: 0,\n    pair, leftSource, rightSource, left: [...left], right: [...right],\n    acceptedContextIds: [...acceptedContextIds], pending: null,\n    status: \"undetermined\", events: [],\n  };\n  const record = {...content, checksum: checksum(content)};\n  durableReplace(location, record);\n  return record;\n});\n\nexport const transactJavaScriptInvestigationCheckpoint = (\n  location: string,\n  event: InvestigationDiskEvent,\n): InvestigationCheckpoint => locked(location, () => {\n  const state = readJavaScriptInvestigationCheckpoint(location);\n  if (!/^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,99}$/.test(event.eventId))\n    throw new Error(\"Invalid checkpoint event ID\");\n  const eventHash = sha(JSON.stringify(event));\n  const previous = state.events.find((row) => row.eventId === event.eventId);\n  if (previous !== undefined) {\n    if (previous.eventHash !== eventHash)\n      throw new Error(\"Conflicting replay of checkpoint event ID\");\n    return state;\n  }\n  if (state.status === \"witnessed-difference\") {\n    if (event.kind !== \"advance\") throw new Error(\"Terminal witness cannot be overwritten\");\n    return state; // no extra revision for a redundant continuation\n  }\n  let left = [...state.left], right = [...state.right];\n  if (event.kind === \"capture\") {\n    if (!state.pending || state.pending.status !== \"proposed\")\n      throw new Error(\"Cannot capture without a source-derived pending request\");\n    if (event.observation.contextId !== state.pending.contextId ||\n        event.observation.inputDigest !== state.pending.inputDigest)\n      throw new Error(\"Captured input does not match pending request\");\n    const records = event.side === \"left\" ? left : right;\n    if (records.some((o) => o.contextId === event.observation.contextId))\n      throw new Error(\"Conflicting or duplicate side capture\");\n    records.push(event.observation);\n  }\n  const step = advanceJavaScriptApplicationInvestigation(\n    state.pair, state.leftSource, state.rightSource, left, right,\n    state.acceptedContextIds, state.pending,\n  );\n  if (step.status === \"blocked-evidence\")\n    throw new Error(\"Blocked checkpoint evidence: \" + step.reason);\n  if (event.kind === \"advance\" && step.status === \"undetermined\" &&\n      state.pending === null && step.request === null)\n    return state; // no unjustified work or duplicate movement\n  const content: Omit<InvestigationCheckpoint, \"checksum\"> = {\n    ...withoutChecksum(state),\n    revision: state.revision + 1,\n    left, right, acceptedContextIds: [...step.acceptedContextIds],\n    pending: step.request,\n    status: step.status,\n    events: [...state.events, {eventId: event.eventId, eventHash,\n      revision: state.revision + 1, resultingStatus: step.status}],\n  };\n  const next = {...content, checksum: checksum(content)};\n  durableReplace(location, next);\n  return next;\n});\n"
def digest(p):return sha256(p.read_bytes()).hexdigest()
def main(action,rea):
    head=subprocess.check_output(["git","-C",str(rea),"rev-parse","HEAD"],text=True).strip()
    if head!=PIN:raise ValueError("pin mismatch")
    matcher=(rea/"src/domain/javascript/javascriptApplicationVersionKeys.ts").read_text()
    if "advanceJavaScriptApplicationInvestigation" not in matcher:
        raise ValueError("requires previous real REA source continuation")
    private=Path("runtime/data/rea-durable-checkpoint").resolve()
    desk=ProcessWorkstation(private/"editions")
    if action=="prepare":
        if (rea/REL).exists():raise ValueError("upstream already has checkpoint module")
        selected=private/"source"
        if selected.exists():raise FileExistsError("control already exists")
        (selected/REL).parent.mkdir(parents=True)
        # Add a control-side evidence file, so the new source edition records an addition.
        (selected/"CONTROL_SCOPE.md").write_text("Original pinned REA has no checkpoint module.\n")
        shutil.copyfile(rea/"LICENSE",selected/"LICENSE")
        shutil.copyfile(rea/"src/domain/javascript/javascriptApplicationVersionKeys.ts",
            selected/"src/domain/javascript/javascriptApplicationVersionKeys.ts")
        control=desk.copy_source(selected,worker_id="rea-checkpoint",
            version_id="control",source_locator="morluto/rea@"+PIN+"+movement11")
        candidate=desk.branch(worker_id="rea-checkpoint",
            parent_version="control",version_id="experimental")
        dst=Path(candidate["path"])/REL
        dst.parent.mkdir(parents=True,exist_ok=True)
        dst.write_text(CONTENT)
        diff=desk.inspect(worker_id="rea-checkpoint",version_id="experimental")
        if diff["added"]!=[REL.as_posix()] or diff["modified"]:
            raise ValueError("unexpected source modifications")
        output=Path("experiments/rea-swallow/results")
        output.mkdir(parents=True,exist_ok=True)
        (output/"restart-edition.json").write_text(json.dumps({
            "upstream":PIN,"parent":"movement11",
            "added_native_source":str(REL),"candidate_sha256":digest(dst),
            "source_fingerprint":control["source_fingerprint"],
            "state":"PENDING_NATIVE_VERIFICATION"},indent=2)+chr(10))
        print("REA_DURABLE_SOURCE_EDITION_CREATED",diff["added"])
    elif action=="apply":
        src=private/"editions/rea-checkpoint/experimental"/REL
        if (rea/REL).exists():raise ValueError("refusing overwrite")
        shutil.copyfile(src,rea/REL)
        subprocess.run(["git","-C",str(rea),"diff","--check"],check=True)
        print("REAL_REA_DURABLE_CHECKPOINT_APPLIED",REL)
    else:raise ValueError(action)
if __name__=="__main__":
    p=argparse.ArgumentParser()
    p.add_argument("action",choices=["prepare","apply"])
    p.add_argument("--rea",type=Path,required=True)
    a=p.parse_args()
    main(a.action,a.rea.resolve())
